    story: '이곳은 먼저, AI의 구성 요소들을 최대한 자유롭게 다루는 일에 관한 곳입니다: 소프트웨어의 기초가 아니라, 그 구성 요소들이 무엇을 수행하고 어떻게 연결되어 여러분만의 구조를 이루는지가 중요합니다. 그리고 두 번째로, 이곳의 작업은 프롬프트에서 결과로 한 방향으로만 흐르지 않습니다 — 질의, 분기, 반복이 가능합니다: 여러분 자신의 기준에 따른 자기비판적 장치입니다.',
