      paragraph2: '일반 교육학(TPap), 컴퓨터 과학(TPinf), 미술 교육(TPkp)의 세 하위 프로젝트에서 창의성 지향적 교육적 AI 실천 연구와 컴퓨터 과학 AI 구상 및 프로그래밍이 긴밀한 협력 속에서 서로 맞물립니다.',
