      generativeAisAlwaysProduce: '생성형 AI는 항상 무작위로 변주된 무언가를 만들어 냅니다. 이들은 설득하도록 훈련되어 있습니다. 통계적으로 확보된 데이터를 바탕으로 결과물을 보여주며, 언제나 무언가를 보여주고 결코 침묵하지 않음으로써(애초에 침묵할 수도 없습니다) 자신이 모르는 것, 낯선 것, 훈련되지 않은 것을 교묘하게 감춥니다. 이러한 공백은 체계적인 비교를 통해 가장 쉽게 드러낼 수 있으며, 이를 통해 AI를 그 다른 측면에서도 알고 이해하는 법을 배울 수 있습니다.',
      languageComparison: '언어 비교',
      theSamePromptDifferent: '동일한 prompt를 여러 언어로 — 동일한 seed로 실행하여, 차이가 오직 언어에서만 비롯되도록 합니다. 이미지 생성 모델은 언어에 따라 다르게 반응하는데, 이는 학습 데이터가 문화와 언어에 걸쳐 고르게 분포되어 있지 않기 때문입니다.',
      linguisticBiases: '언어적 편향',
      theLanguageComparisonEnables: '언어 비교를 통해 AI의 언어 및 문화 관련 불평등한 처리를 체계적으로 탐구할 수 있습니다. 영어 prompt는 종종 미국-서구적 색채가 짙은 이미지를 만들어 냅니다. 동일한 내용을 다른 언어로 입력하면 학습 데이터가 얼마나 불균등하게 분포되어 있는지, 그리고 모델의 편향이 어디에 있는지가 드러납니다.',
