      languageCarriesCulturalLayers: '언어는 문화적 의미의 층위를 담고 있습니다. 번역 가능한 하나의 단어라도 언어마다 서로 다른 연상을 불러일으키며, 모델은 이러한 차이를 그대로 반영합니다.',
      modelComparison: '모델 비교',
      differentModelsInterpretSame: '서로 다른 모델들은 동일한 노이즈 이미지를 기반으로 동일한 prompt를 해석하지만 — 전혀 다른 결과를 만들어 냅니다. 모델 비교는 prompt뿐 아니라 모델 자체가 결정적인 변수임을 드러내 보여줍니다.',
      currentTopModels: '현재의 최상위 모델',
      sd35Large: 'SD 3.5 Large, Flux 2, Gemini 3 Pro — 현재의 세 모델을 직접 비교합니다.',
      historicalComparison: '역사적 비교',
      sd152022: 'SD 1.5 (2022), SDXL (2023), SD 3.5 Large (2024) — 세 세대. 이미지 생성은 해마다 어떻게 변화해 왔을까요?',
      temperatureComparison: '온도 비교',
      theSameTextSent: '동일한 텍스트가 동일한 언어 모델에 세 가지 다른 온도 설정으로 동시에 전달됩니다. 온도는 모델이 가장 가능성 높은 단어 순서에서 얼마나 벗어나는지를 결정합니다: 낮은 온도에서는 텍스트가 예측 가능한 범위에 머물고, 높은 온도에서는 점점 더 놀랍고 예측할 수 없는 표현이 나타나며 — 결국 일관된 텍스트가 와해되는 지점까지 이릅니다.',
      controlLossControl: '통제와 통제 상실',
      theComparisonMakesSpectrum: '이 비교는 통제와 통제 상실 사이의 스펙트럼을 보여줍니다: 모델은 어디까지 우리의 기대를 따르고, 어디서부터 자신만의 길을 가기 시작하며, 어디서 텍스트가 더 이상 조종할 수 없는 무언가로 와해되는가?',
      systemPromptComparison: '시스템 Prompt 비교',
      theSameMessageSent: '동일한 메시지가 동일한 언어 모델에 동시에 전달되지만 — 세 가지 다른 system prompt와 함께 전달됩니다. system prompt는 사용자가 말하기 전에 모델에게 주어지는 보이지 않는 지시입니다. ChatGPT, Claude, Gemini 등 모든 상업적 AI 제품은 이러한 숨겨진 지시와 함께 작동합니다. 이 모드는 그것을 보이게 하고 편집할 수 있게 만듭니다.',
      makingInvisibleVisible: '보이지 않는 것을 보이게 하기',
      presetsIncludeClaudeS: '프리셋에는 Claude의 실제 제품 prompt, 교육적 prompt(해적, 시인, 다섯 살 아이), 그리고 어떠한 조종도 없이 모델의 "날것" 그대로의 행동을 보여주는 빈 prompt가 포함되어 있습니다. 모든 prompt는 직접 편집할 수 있습니다.',
      identityThroughInstruction: '지시를 통한 정체성',
      theSameModelBecomes: '동일한 모델이 협조적이거나, 반골적이거나, 시적이거나, 유치한 존재가 됩니다 — 오직 system prompt를 통해서만 말이죠. 모델 자체는 변하지 않고, 조종 방식만 달라질 뿐입니다. 이는 다음을 보여줍니다: AI의 "인격"은 타고난 특성이 아니라 하나의 구성입니다.',
      voices: '목소리',
      culturalUnderstanding: '고정관념 분석',
      culturalUnderstandingBody: '첫 번째 열은 프롬프트 그 자체입니다. 이름을 하나 덧붙일 때마다 — 문화 하나, 국가 하나 — 그 옆에 열이 하나씩 더 서며, 같은 프롬프트에서 별표가 있던 자리에 그 이름이 들어갑니다. 여러 모델을 고르면 각 행이 그중 하나이고, 열은 모든 행에서 같습니다. 모델을 하나만 고르면 각 행은 같은 모델에 다른 난수를 쓴 것이며, 그때 행들은 같은 프롬프트를 여러 번 뽑은 결과입니다.',
      aiAssistedAnalysis: 'AI 지원 분석',
      inAllFourComparison: '네 가지 비교 모드 모두에서 도움말이 결과와 함께 제공됩니다. 모델이 만들어낸 것에 대해 설명하고, 차이점을 짚어 주며, 비교를 교육적으로 유의미하게 만드는 질문을 던집니다.',
      notJustSeeingBut: '보는 것을 넘어 이해하는 것으로',
      theComparisonAloneShows: '비교만으로도 차이가 드러납니다. AI 지원 분석은 이러한 차이를 맥락화하는 데 도움을 줍니다: 왜 이미지는 한국어에서와 영어에서 다르게 보일까요? 역사적 모델 비교는 학습 데이터의 발전에 대해 무엇을 말해 줄까요?',
