      generativeImageModelsClosed: '생성형 이미지 모델은 폐쇄적인 시스템입니다: 이들은 대기업이 방대한 데이터셋으로 학습시키며, 그 데이터셋은 개인이 들여다보거나 영향을 미칠 수 없습니다. 전문가라 해도 이러한 모델을 쉽게 학습시킬 수는 없습니다 — 비용, 데이터, 하드웨어가 개인의 역량을 훨씬 뛰어넘기 때문입니다.',
