      promptInterceptionLlmCo: 'Prompt Interception: 공동 행위자로서의 LLM',
      conventionalAiInterfacesTurn: '기존의 AI 인터페이스는 사용자를 명령을 내리는 동시에 기계의 논리에 종속되는 존재로 만듭니다. Prompt Interception은 이 패턴을 깨뜨립니다: LLM은 당신이 원하는 대로 해 주는 도구가 아니라 — 과정에 새로움과 예측 불가능성을 끌어들이는 공동 행위자입니다. 그것은 해석하고, 선택하고, 덧붙입니다. 결과물은 당신의 필체와 모델의 필체를 함께 지닙니다. 기계는 당신의 창조적 생성 과정에 봉사합니다 — 그 반대가 아닙니다.',
