      collaboration: '협업',
      theFavoritesSystemAt: '창 하단에 있는 즐겨찾기 시스템은 두 가지 작업 방식을 가능하게 합니다: "내 즐겨찾기"는 오직 자신의 즐겨찾기만 보여주며 — 초안을 반복하고, 비교하고, 선택하기 위한 개인적인 작업 공간입니다. 개별 "내" 즐겨찾기는 24시간 후 삭제됩니다. "전체"는 모든 워크숍 참가자의 즐겨찾기를 보여줍니다 — 이미지와 prompt를 공유하고, 서로에게 영감을 주고, 함께 발전시켜 나가기 위한 공동의 저장소입니다.',
