    tokenCut: 'CLIP 블록을 넘어서는 조각 {n}개는 T5에만 닿습니다. | CLIP 블록을 넘어서는 조각 {n}개는 T5에만 닿습니다.',
    tokensUnavailable: '토크나이저 요청이 {status} 상태로 실패했습니다: {reason}',
    noteBody: 'Encoder Fusion은 이미지 모델 Stable Diffusion 3.5가 그림을 계산하기 전에, 그 계산의 바탕이 되는 숫자 표를 바꿉니다. 그림은 그 표, 곧 컨디셔닝 표를 보여 주며, 세 텍스트 인코더가 프롬프트에서 그것을 채웁니다. 두 CLIP 인코더 CLIP-L과 CLIP-G는 위쪽 77행을 4096열 가운데 2047열까지 채우고, 그 뒤의 열들은 0으로 남습니다. 인코더 T5-XXL, 그림 속의 T5는 그 아래 512행을 모든 열에 걸쳐 채우며, 프롬프트에 T5 조각이 더 많으면 더 많은 행을 채웁니다. 각 행은 프롬프트의 조각 하나, 시작 표시나 끝 표시, 또는 텍스트가 끝난 뒤의 패딩을 담으며, 토큰 표는 CLIP과 T5에서 어느 조각이 어느 행에 서는지를 나열합니다. 세 계수가 두 블록에 작용합니다: a는 CLIP 블록에 곱해지고, c는 T5 블록에 곱해지며, b는 T5의 0–76행을 칸마다 CLIP 블록에 더합니다. T5의 각 행이 같은 번호의 CLIP 행 위에 더해지며, 두 행에 어느 조각이 들어 있든 그렇습니다. T5 블록은 이 행들을 모두 담거나, 이전 Surrealizer의 배치에서는 77–511행만 담으며, 그러면 T5의 0–76행은 CLIP 블록 안에서 b배로 더해지는 항으로만 모델에 닿습니다. 표 옆에서 모델은 풀링된 벡터, 그림 속의 pool을 읽습니다: CLIP-L의 768개와 CLIP-G의 1280개 숫자를 이어 붙인 것입니다. CLIP 블록 위의 막대가 그것을 보여 주며, pool CLIP에서는 채워져 있고 pool 0에서는 비어 있어 그 자리에 0들이 섭니다. 어느 쪽인지는 a의 줄에 있는 두 필드가 정합니다. Standard는 a 1, b 0, c 1, pool CLIP입니다: 이 도구가 없을 때 그대로 서 있는 표와 벡터입니다.\n\nEsser et al.(2024)은 이 표를 Stable Diffusion 3에 대해 기술합니다: CLIP 행은 0으로 4096열까지 채워지고, T5 행은 그 아래에 놓이며, 학습에서는 세 인코더가 각각 서로 독립적으로 무작위로 0이 되어, 그림을 만들 때 모델이 그중 어떤 부분집합으로도 실행됩니다. 풀링된 벡터와 모델이 서 있는 스텝은 그들의 아키텍처에서 변조의 두 입력입니다: 모델의 각 층이 자신을 지나가는 것의 크기를 조절하고 위치를 옮기는 데 쓰는 숫자입니다(4절). T5 블록 없는 표, 여기서는 CLIP만에 대해 저자들은 “limited performance drops when using only the two CLIP-based text-encoders for the text prompts and replacing the T5 embeddings by zeros”라고 보고하며, 자세한 장면 묘사와 쓰인 텍스트를 예외로 듭니다. b가 0보다 클 때 생기는, 두 인코딩이 함께 들어 있는 행은 이 학습된 상태들 밖에 놓입니다. 그런 표로부터 모델이 무엇을 계산하는지가 이 도구의 질문입니다.',
    referencesTitle: '연구 참고문헌',
