      headerSubtitleDetail: '디퓨전 모델이 텍스트로부터 이미지를 생성하는 방식을 살펴보는 여덟 가지 도구입니다. 이들은 어디에 개입하는지에 따라 나뉩니다. 텍스트 인코더는 프롬프트를 하나의 고정된 임베딩으로 바꾸고, 그 임베딩이 25단계의 디노이징 전 과정을 이끕니다. Dimension Explorer, Concept Algebra, Encoder Fusion은 루프가 시작되기 전에 임베딩을 한 번 바꾸며, Encoder Fusion Workbench는 융합 매개변수를 세 축에 걸쳐 훑어봅니다. Composable Diffusion은 모든 임베딩을 그대로 두는 대신, 각 단계마다 모델이 반환하는 값들을 조합합니다. Denoising Archaeology와 Attention Cartography는 아무것도 바꾸지 않고 관찰만 합니다. Mean Images 역시 모델을 그대로 둔 채 많은 그림을 하나로 평균 냅니다. 두 SD 3.5 모델에서는 그 그림들의 잠재 표현을 디코더 앞에서 평균 냅니다.',
