      origin: '슈타이얼은 mean images에서 ‘통계가 있음직함(likeliness)의 규정을 통해 대상의 닮음(likeness) 속으로 곧바로 통합된다’고 씁니다(Steyerl 2025, p. 78). 즉 어떤 사물의 그림이 상상과 미메시스가 아니라 확률로부터 계산된다는 것입니다. 이 페이지에서 당신은 *mean 방법*을 생성형 AI 모델에 되돌려(또는 그것에 맞서) 적용합니다: 비슷한 프롬프트들로, 또는 하나의 프롬프트를 서로 다른 시작 시드로 돌려 많은 이미지를 생성하고 그 모든 이미지의 시각적 ‘평균(mean)’을 세움으로써, 시각적 클리셰, 편견, 그리고 ‘정상성’의 통계적 생산이 취하는 다른 형태들을 탐구하고 견주어 볼 수 있습니다.',
      steyerl: '예술가 히토 슈타이얼은 AI 모델이 생성하는 그림을 ‘mean images’, ‘상관된 평균들의 표현’이라고 부릅니다: 통계적 평균으로 만들어진 이미지입니다. 영어 낱말 ‘mean’은 ‘여러 뜻을 가지며, 그 뜻이 모두 여기에 해당한다’고 그는 씁니다: ‘“Mean”은 보잘것없거나 초라한 출신을, 규범을, 인색함을, 또는 고약함을 가리킬 수 있다.’ 그는 이렇게 씁니다: ‘Mean images는 무작위적인 환각과는 거리가 멀다. 그것은 데이터 포퓰리즘의 예측 가능한 산물이다. 그것은 상충하는 의미들을 벡터 좌표로 부호화하는 잠재적 사회 패턴을 집어 든다. 그것은 흔한 것을 하층 계급의 지위, 범용함, 고약한 행동과 나란히 놓는, 실재하는 사회적 태도를 시각화한다.’ (Steyerl 2025, p. 72)',
