      noteBody: 'LoRA 어댑터는 모두 같은 낱말로 시작하는 캡션으로 학습되며, 그 낱말이 어댑터를 부릅니다. 어댑터가 다른 것에도 응답하는지는 그것을 받아들인 모델에 관한 질문입니다: 개인화는 흘러가는 것으로 알려져 있어, 한 낱말이 새로 얻은 의미와 함께 그 낱말의 본래 의미도 달라집니다. 네 개의 행은 이것을 측정하는 프로토콜입니다 — 트리거와 함께 그리고 트리거에 맞서, 어댑터와 함께 그리고 어댑터 없이.',
      noteLimits: '행들이 열어 두는 것이 둘 있습니다. 각 셀은 한 번의 뽑기이므로, 두 셀 사이의 차이는 하나의 사례입니다 — 이것이 따르는 프로토콜은 무엇인가를 결과라고 부르기 전에 많은 프롬프트와 많은 뽑기에 걸쳐 보고합니다. 그리고 여기의 트리거 단어는 일상 언어이므로, 세 번째 행은 두 가지 효과를 한꺼번에 담습니다: 학습이 그 낱말에 묶어 놓은 것과, 그 낱말이 모델에게 이미 뜻하던 것입니다. 이 둘을 갈라내려면 이 네 상태에는 자리가 없는 또 하나의 상태가 있어야 합니다.',
