        noteBody: '관점 아래 서는 모든 그림은 같은 템플릿에서 출발하고, 이 플랫폼이 Interception에 쓰도록 설정된 언어 모델이 그 프롬프트를 쓰며, 이미지 모델을 위한 같은 적응 단계를 거치고, 같은 Seed로 생성됩니다 — 그래서 두 그림 사이의 유일한 차이는 관점입니다.\n\n표현과 그림은 함께 갑니다. 낱말이 무엇을 가리키는지만으로 그런 것은 아닙니다. De Rosa Palmini and Cetinic (2025)은 공개된 이미지 플랫폼의 서로 다른 프롬프트 270만 개를, 표현을 얼마나 공유하는지에 따라 묶었습니다: 낱말의 80% 이상을 공유하는 묶음은 50에서 70%를 공유하는 묶음보다 한결같이 더 균질한 그림을 동반했고, 표본으로 삼은 여러 달에 걸쳐 표현이 풍부하고 덜 반복될수록 그림은 더 다양했습니다(Vendi score로 측정). 프롬프트가 말하는 것과 그림이 보여 주는 것은 여전히 별개입니다: Stable Diffusion에서는 어떤 고정관념에 명시적으로 맞서 쓴 수식어가 그 고정관념을 그대로 남겨 두는 일이 잦았습니다 — ‘a white poor person’은 여전히 대부분 어두운 피부의 얼굴을 만들어 냈고, ‘a photo of an African man and his fancy house’는 여전히 소박한 오두막을 만들어 냈습니다 (Bianchi et al. 2023).',
