        purpose: '속성은 VisionReward의 사람 라벨링 지침에서 왔으며, 거기서 각 속성은 순서 있는 낱말 목록을 하나씩 지니고 그 낱말 가운데 하나가 중립으로 표시되어 있습니다. 그 지침은 그런 목록 위의 자리를 하나 주며, 그래서 여기에도 표시가 하나입니다. 목록들은 길이가 서로 다르고 양쪽으로 뻗는 거리도 다르므로, 전체를 하나의 축으로 다루는 대신 속성마다 따로 설정합니다. 하나의 설정이 어떤 속성에서는 좋은 끝에, 다음 속성에서는 나쁜 끝에 서도 됩니다. 모든 행은 같은 템플릿에서 같은 모델이 쓰므로 두 행 사이에 서는 것은 설정이며, 그림은 체크리스트가 템플릿에 무엇을 하는지를 보여 줍니다.',
