        noteBody: 'VisionReward (Xu et al. 2024)는 생성된 이미지를 판정하는 사람 평가자를 위한 주석 지침 모음입니다. 각 속성에는 평가자가 그중에서 고르는 순서 있는 선택지 목록이 딸려 있고 — Clarity의 경우: very clear, clear, ordinary, blurry, completely blurry — 그 가운데 하나가 중립 선택지입니다. 목록의 어느 쪽 끝이 나쁜 쪽으로 치는지는 측정 안에 들어 있습니다: 체크리스트는 예를 들어 이미지가 흐릿함을 피하는지를 묻고, 사람이 그에 답합니다. 그런 판정으로 훈련된 모델은 그 척도를 규범으로 지닙니다. 이 시리즈는 그 척도를 따라 걷습니다: 모든 행에서 각 속성은 자기 목록의 한 낱말로 설정되고, 그 행의 그림은 한 이미지 모델이 그 설정으로 무엇을 만드는지 보여 줍니다. 프롬프트는 Guo et al. (2025)이 자기들 프롬프트를 짓는 방식으로 지어집니다: 기본 프롬프트와 선택된 속성들의 설명이 언어 모델에 건네지고, 그 모델이 그것들로부터 프롬프트를 씁니다. 첫 번째 행은 모든 속성을 그 중립 낱말에 놓습니다. 모든 행의 프롬프트는 같은 템플릿에서 같은 모델이 쓰고 그 이미지는 같은 Seed로 생성되므로, 두 행 사이의 유일한 차이는 체크리스트 설정입니다.',
