      explainWhatText: '디퓨전 모델이 이미지를 생성할 때, 프롬프트를 단어별로 읽지 않습니다. 대신 "어텐션"이라는 메커니즘이 각 단어의 영향을 다른 이미지 영역에 분배합니다. "집"이라는 단어는 주로 집이 나타나는 영역에 영향을 미치지만 — 모델이 전체 장면의 맥락을 이해하기 때문에 인접 영역에도 영향을 미칩니다. 이 도구는 그 분포를 눈에 보이게 만듭니다: 클릭한 단어는 그것이 가장 크게 영향을 미친 이미지 영역을 보여 줍니다.',
