      techTitle: '기술 세부사항',
      techText: 'SD3.5는 공동 어텐션을 사용하는 MMDiT(멀티모달 디퓨전 트랜스포머)를 사용합니다: 이미지와 텍스트 토큰이 24개의 트랜스포머 블록에 걸쳐 서로 주의를 기울입니다. 이 도구는 텍스트→이미지 어텐션 부분 행렬을 추출하기 위해, 선택된 3개 블록에서 기본 SDPA 프로세서를 수동 softmax(QK^T/√d) 프로세서로 교체합니다. 맵은 64x64 해상도(패치 격자)이며, 쌍선형 보간으로 이미지 해상도까지 업스케일됩니다. SD3.5에는 세 개의 텍스트 인코더가 있습니다 — CLIP-L(BPE, 77토큰), CLIP-G(BPE, 77토큰), T5-XXL(SentencePiece, 512토큰). 이 중 두 개를 여기서 켜고 꺼서 서로 다른 토큰화 전략이 어텐션에 미치는 영향을 볼 수 있습니다.',
