      explanationToggle: '자세한 설명 보기',
      explainWhatTitle: '이 도구는 무엇을 보여주나요?',
      explainWhatText: '2013년 Mikolov는 단어 임베딩이 의미적 관계를 선형 방향으로 인코딩한다는 것을 보였습니다: "왕" 벡터에서 "남자"를 빼고 "여자"를 더하면 "여왕"에 가까운 벡터가 나옵니다. 이 도구는 그 발상을 SD3.5의 텍스트 인코더에 적용합니다: 단어 하나가 아니라 프롬프트 임베딩 전체를 다룹니다. 결과는 A로부터 B→C 방향을 따라 멀어진 이미지입니다. 얼마나 멀어졌는지, 그리고 어떤 측면에서 멀어졌는지를 들여다볼 수 있게 해주는 것이 이 도구입니다.',
      explainHowTitle: '대수학은 어떻게 작동하나요 — 왜 네거티브 프롬프트를 사용하지 않나요?',
      explainHowText: '세 개의 프롬프트를 입력합니다: A(기본), B(빼기), C(더하기). 공식은 다음과 같습니다: 결과 = A − 스케일₁×B + 스케일₂×C. 스케일 슬라이더는 강도를 조절합니다: 1.0에서는 B가 완전히 빠지고 C가 완전히 더해집니다. 0.5에서는 절반만 적용됩니다. 1.0을 넘는 값은 효과를 증폭시킵니다. — 그냥 "A + C"를 프롬프트로, "B"를 네거티브 프롬프트로 쓰면 안 될까요? 두 가지가 서로 다른 곳에서 일어나기 때문입니다. 네거티브 프롬프트는 가이던스를 측정하는 기준선이므로, 디노이징 루프 안에서 25단계 각각에서, 현재 상태의 이미지에 대해 작동합니다. 개념 대수학은 생성 전에 새로운 벡터를 계산합니다: 산술 연산은 임베딩 공간에서 단 한 번 일어나며, 루프는 무언가가 빠졌다는 사실을 전혀 알지 못합니다. — 이 뺄셈이 하지 않는 것은 이름 붙여진 대상을 삭제하는 일입니다. 이 플랫폼에서 진행한 자체 측정 시리즈에 따르면, 한 프롬프트 벡터에서 다른 벡터를 빼면 톤, 프레이밍, 어조는 바뀌지만 이름 붙여진 대상은 그림 속에 남습니다. 결과는 제거가 아니라 의미 공간에서의 변위로 읽어야 합니다.',
      explainReadTitle: '결과의 의미는 무엇인가요?',
      explainReadText: '왼쪽에 참조 이미지(프롬프트 A만, 동일 시드)가, 오른쪽에 대수학 결과가 보입니다. 유추가 작동하면 오른쪽 이미지는 개념 A를 보여주되 의미적 변화 B→C가 적용되어야 합니다. L2 거리는 결과가 원본으로부터 얼마나 이동했는지 보여줍니다.',
