      headerTitle: '컴포저블 디퓨전 — 각 개념에 별도의 에너지',
      headerSubtitle: '프롬프트 전체를 하나의 거대한 벡터로 인코딩하는 대신, 각 개념은 디노이징 중에 자기만의 트랜스포머 패스를 거칩니다.',
      explanationToggle: '자세한 설명 보기',
      explainWhatTitle: '이 도구는 무엇을 하나요?',
      explainWhatText: '표준 이미지 생성은 프롬프트 전체를 하나의 표현으로 압축합니다. 모델은 "호숫가의 빨간 집"을 하나로 융합된 개념으로 봅니다. 컴포저블 디퓨전은 이것을 분리합니다: "빨간 집"과 "호수"는 각각 모든 디노이징 스텝에서 신경망을 통해 자기만의 완전한 처리 패스를 거칩니다. 그런 다음 그 예측들은 조정 가능한 가중치로 결합됩니다. 이는 각 개념에게 자신만의 "에너지 함수" — 이미지가 어떤 모습이어야 하는지에 대한 자기만의 투표권을 부여합니다. 개념에 음의 가중치를 줄 수도 있습니다. 그러면 그 개념은 섞여 들어가는 대신, 양의 방향들과 나란히 자신만의 반대 방향으로서 매 스텝마다 빠집니다. 그것으로 무엇이 이루어지는지는 무엇이 부정되는지에 달려 있습니다: 그림 속에 하나의 사물로 나타나는 것은 밀어낼 수 있지만, 양의 프롬프트 속 대상에 결부된 속성이나 스타일 전체는 제거되지 않습니다 — 이미지는 그저 물러날 뿐이며, 음의 가중치가 커지면 내용을 잃고 결국 과도해집니다. 이것 역시 네거티브 프롬프트와는 다른 연산입니다. 네거티브 프롬프트는 이미지가 비교되는 기준선 자체를 바꾸기 때문입니다.',
      explainHowTitle: '기술적으로 어떻게 작동하나요?',
      explainHowText: '25번의 디노이징 스텝마다, 모델은 N+1번의 트랜스포머 패스를 실행합니다: 네거티브 프롬프트(비조건부)를 위한 패스 하나와, 각 개념을 위한 패스 하나씩입니다. 각 개념은 자신만의 노이즈 예측을 만들어냅니다 — 그리고 합산에 들어가는 것은 그 예측 자체가 아니라, 비조건부 예측과의 차이입니다: noise = uncond + v1×(noise_1 - uncond) + v2×(noise_2 - uncond) + ... 여기서 각 v는 그 개념 고유의 가이던스 강도입니다. 양의 v는 이미지를 그 개념 쪽으로 끌어당기고(AND), 음의 v는 밀어냅니다(NOT). 모든 개념이 매 스텝마다 따로 채점되기 때문에, 어느 것도 다른 것에 흡수될 수 없습니다 — 이는 하나로 융합된 프롬프트 안에서 정확히 벌어지는 일과 대조적입니다.',
      techTitle: '기술 세부사항',
      techText: 'Liu 외 (2022) 연구의 식 11(결합)과 식 15(부정)에 기반합니다. 각 개념은 SD3.5의 세 인코더(CLIP-L, OpenCLIP-G, T5-XXL) 모두로 독립적으로 인코딩됩니다. 커스텀 디노이징 루프는 스텝마다 개념 하나당 pipe.transformer()를 한 번씩 호출합니다. 가중치는 두 가지 방식 중 하나로 해석됩니다. "정규화"가 켜져 있으면 가중치는 CFG 값을 나눈 몫이 됩니다: 전체 가이던스는 CFG로 유지되므로, 개념을 추가할수록 각각의 몫은 더 작아집니다. 꺼져 있으면 각 가중치는 그 개념 고유의 가이던스 온도가 되어, v = CFG × 가중치이며, 음의 가중치는 NOT 연산자입니다 — 이는 논문의 eps_u + w×(eps_a - eps_b)와 대수적으로 동일합니다. 음의 가중치는 정규화를 자동으로 끕니다. 부호가 섞인 혼합은 의미가 없기 때문입니다. VRAM: 모델 가중치는 패스 간에 공유되며, 활성화 값만 달라집니다. 개념이 4개면 생성 시간은 표준보다 약 4배 더 걸립니다(각 스텝마다 2번이 아니라 5번의 트랜스포머 패스가 필요하기 때문입니다).',
