      explainHowText: '프롬프트를 입력하고 작업면 위쪽 막대의 삼각형으로 실행을 시작하세요. 모델은 디노이징 스텝마다 중간 이미지를 하나씩 내놓습니다. 그중 하나가 한 번에 화면을 채우고, 왼쪽 열의 슬라이더가 실행의 구간들을 이름 짓습니다. 슬라이더를 따라 움직이면 한 이미지에서 다음 이미지로 넘어갑니다. 초기 스텝과 후기 스텝을 비교해 보세요: 어느 스텝에서 그림이 노이즈에서 장면으로 바뀌나요?',
      explainReadTitle: '세 구역',
      explainReadText: '초기 스텝: 전역 구성 — 기본 구조, 색 분포, 레이아웃 계획. 중간 스텝: 의미적 출현 — 사물이 알아볼 수 있게 되고 형태가 또렷해집니다. 후기 스텝: 세부 정제 — 질감, 가장자리, 미세 패턴. 전환은 점진적이며, 세 구역은 작업 좌표이지 검증된 경계가 아닙니다: Choi et al. (2022)은 거친 구조 / 내용 / 마무리의 구분을 가설로 세우지만, 그것을 스텝 번호가 아니라 노이즈 수준으로 자리매김하며, 생성 실행이 아니라 학습 중에 측정합니다. 특히 눈여겨볼 점: 맨 첫 스텝은 고운 픽셀이 아니라 색 얼룩을 보여줍니다. 노이즈가 픽셀 공간이 아니라 잠재 공간(16채널의 128×128)에서 생성되기 때문입니다. VAE는 각 잠재 픽셀을 약 8×8 픽셀의 조각으로 옮기므로 — 순수한 가우시안 노이즈조차 일관된 색 덩어리가 됩니다. 계산은 개별 픽셀이 아니라 이 압축된 공간에서 처음부터 끝까지 이루어집니다.',
      techTitle: '기술 세부사항',
      techText: '여기서는 두 개의 백본이 실행됩니다: SD 3.5 Large는 rectified-flow 트랜스포머로 스케줄러가 FlowMatchEuler 하나뿐이고, SDXL은 U-Net으로 스케줄러를 목록에서 고릅니다. SD 3.5는 여기에 더해 shift를 지니는데, 이것이 스텝을 노이즈 스케일 위에 펼쳐 놓습니다. 자체 스케줄러 설정은 그 값을 3.0으로 둡니다. 25스텝이 기본값입니다. 각 스텝에서 현재의 잠재 벡터가 VAE(Variational Autoencoder)를 통해 디코딩되며, VAE는 수학적인 잠재 공간을 픽셀로 옮깁니다. 잠재 표현은 16채널에 걸친 128×128이며 — 각 잠재 지점은 이미지에서 약 8×8 픽셀의 조각에 해당합니다. 첫 스텝조차 고운 픽셀 노이즈가 아니라 색 덩어리를 보여주는 이유가 여기에 있습니다: VAE가 무작위 16차원 벡터를 일관된 색 면으로 옮기기 때문입니다. 화면에 보이는 것은 모델이 예측한 완성 이미지가 아니라, VAE를 통해 디코딩된 노이즈 섞인 중간 상태입니다 — 그 예측은 Ho et al. (2020)이 자신들의 그림에서 보여 줍니다.',
      referencesTitle: '연구 참고문헌',
      noteBody: '이미지 생성기는 노이즈로부터 스텝을 밟아 그림을 세워 올리며, 각 스텝은 서로 다른 일을 합니다: Choi et al. (2022)은 거친 배치가 높은 노이즈에서, 내용이 중간에서, 표면이 끝에서 정해진다고 측정했습니다. 이들은 단일 실행의 스텝 번호가 아니라 노이즈 수준으로, 그리고 학습 중에 측정했습니다 — 실행 안의 한 자리로서 대략적인 방향 표시이며 검증된 경계는 아닙니다. 맨 처음 그림은 순수한 노이즈 그림입니다: 고운 입자가 아니라 색 얼룩으로 보이는데, 축소된 노이즈 공간의 각 점이 이미지에서 약 8 × 8 픽셀의 면이 되기 때문입니다. 두 신경망은 텍스트를 서로 다르게 받아들입니다: SDXL의 U-Net에서는 텍스트가 그대로 있는 동안 이미지가 크로스 어텐션을 통해 텍스트에 손을 뻗고, SD 3.5의 MMDiT에서는 이미지 부분과 텍스트 부분이 각자의 가중치를 지닌 채 같은 어텐션 메커니즘을 지나며 서로 양방향으로 작용합니다 (Esser et al. 2024).',
