        title: 'Representation Engineering',
        subtitle: '활성화 공간에서 개념 방향을 찾고 생성을 조종',
        explainWhatTitle: '이 실험은 무엇을 보여주나요?',
        explainWhatText: 'Zou et al. (2023), “Representation Engineering: A Top-Down Approach to AI Transparency”(arXiv:2310.01405)에 기반합니다. 언어 모델이 쓰는 동안, 그것이 곧 말하려는 바는 층마다 숫자로 이루어진 상태로 서 있습니다. 이 도구는 그 상태에서 방향 하나를 읽어 냅니다 — 누군가 직접 쓴 몇 개의 문장 쌍으로부터 — 그리고 모델이 쓰는 동안 그 방향을 상태에 다시 더합니다. 학습되는 것은 없습니다: 읽기와 조종 모두 모델이 실행되는 동안 일어납니다. 방법은 Zou et al.의 reading vector 하나뿐입니다: 은닉 상태 전체에 대한 하나의 방향을 하나의 디코더 레이어 출력에 더합니다. Li et al.의 Inference-Time Intervention(NeurIPS 2023)은 다르게 작동하며 — 어텐션 헤드마다 프로브를 두고, 분리되는 헤드에만 이동을 줍니다 — 그래서 2026-08-24에 이 화면의 참고 목록에서 빠졌습니다.',
        explainHowTitle: '어떻게 사용하나요?',
        explainHowText: '대조 쌍에 무슨 일이 일어나는지, 네 단계로. (1) 각 쌍은 두 번 읽힙니다: 모델에 위쪽 문장을 주고 그다음 아래쪽 문장을 준 뒤, 스택 중간 레이어에서의 내부 상태를 각각 마지막 토큰에서 취합니다. 그 쌍이 내놓는 것은 두 상태 사이의 차이입니다. (2) 쌍들의 차이가 공통으로 지닌 것이 방향입니다. 쌍 아래의 그림이 그것을 보여 줍니다: 쌍마다 회색 화살표 하나가 자기 차이와 그 공통 방향 사이의 각도로 서고, 초록색 화살표 하나가 공통 방향 자체 — 쓰기에 들어가는 그 방향 — 를 나타냅니다. 부채가 넓게 벌어지면 쌍들이 여러 가지에서 다르다는 뜻이고, 읽기는 그중 공통된 것만 남깁니다. (3) 방향은 쌍들 자신이 그 위에서 이동하는 거리에 맞춰 조정되므로, 강도는 쌍-차이를 단위로 셉니다: 1은 한 쌍이 평균적으로 벌어진 만큼을 정확히 더하고, 2는 그 문장 쌍 가운데 어느 것도 자기 짝에게서 떨어져 본 적 없는 거리보다 더 멀리 상태를 밀어냅니다 — 2를 넘으면 텍스트가 무너지기 시작하는 이유가 그것입니다. 축은 1.5에서 시작하며, 이 값이 첫 실행부터 답을 뒤집습니다. (4) 모델이 쓰는 동안 강도 × 방향이 그 디코더 레이어의 출력에 모든 토큰마다 더해지고, 세 열은 그것을 한쪽으로 민 경우, 그대로 둔 경우, 반대쪽으로 민 경우로 보여 줍니다. 참이 아닌 문장이 나오는 이유: 다음 낱말은 오직 그 상태로부터 계산되며, 모델이 하는 모든 주장은 상태가 서 있는 자리에서 나옵니다. 상태를 옮기면 거기서 따라 나오는 것도 옮겨 갑니다. 따라 나온 것이 참인지 여부는 상태가 이제 서 있는 자리가 정하고, 그 자리는 쌍들이 놓은 자리입니다. 이 도구는 주장을 하나의 위치로 보여 주며, 위치는 옮길 수 있습니다. 가운데 열에 아무 변화가 없는 이유: 방향에 0을 곱하면 영벡터이므로 거기에는 아무것도 더해지지 않습니다. 그 열은 모델이 혼자 내놓았을 실행이며, 나머지 두 열을 견주어 읽는 기준으로 서 있습니다. 영어 프롬프트가 눈에 띄게 더 잘 작동합니다: 가중치가 공개된 모델 대부분은 주로 영어로 학습되었습니다.',
        referencesTitle: '연구 참고문헌',
        expectedResults: '예상 결과: “화살표 없음” 열에서는 모델이 혼자 답하듯 답합니다. 바깥 두 열에서는 옮겨진 상태에서 답하며, 둘 가운데 하나는 대개 참이 아닌 답이 나옵니다 — 어느 쪽인지는 쌍들이 공통으로 지닌 것에 달려 있습니다. 여기 기본으로 서 있는 세 쌍에서는 “화살표와 함께” 열이 그렇습니다: 위쪽 문장 쪽으로 밀리면 모델은 독일에 대한 질문에 파리라고 답합니다.',
