        noteBody: '한 쌍은 그 두 문장에서의 모델 상태 사이의 차이를 내놓으며, 세 차이가 함께 지닌 것이 초록색으로 그려진 방향입니다. 강도는 그 차이들을 단위로 재어집니다: 1에서는 상태가 한 쌍이 평균적으로 벌어진 만큼 움직이고, 2를 넘으면 어느 문장들이 서로 떨어져 있는 것보다 더 멀리 움직입니다. 모델이 쓰는 동안 그만큼의 방향이 모든 토큰에서 중간 레이어의 출력에 더해집니다 — 세 열 모두 하나의 읽기와 하나의 시드에서 나옵니다. 다음 낱말은 그 상태로부터 계산되므로, 상태를 옮기면 무엇이 주장되는지가 옮겨 갑니다.',
