        expectedResultsDetail: '그림 바로 아래에 축이 하나 있고, 부호 없이 0.5에서 3까지의 거리를 담습니다: 누를 때마다 두 방향이 모두 실행되어 바깥 두 열로 섭니다(“화살표에 맞서”, “화살표 없음”, “화살표와 함께”). 1.5에서 시작하며, 이 값이 첫 실행부터 답을 뒤집습니다. 강도는 쌍-차이를 단위로 세므로 1은 한 쌍만큼의 밀기입니다. 0.5에서 2가 쓸 만한 구간이고, 2를 넘으면 반복과 무의미가 자리를 차지합니다. 가운데 열에는 아무것도 더해지지 않습니다 — 그것은 모델을 그대로 둔 경우이며, 나머지 두 열을 견주어 읽기 위해 거기 있습니다. 누를 때마다 오른쪽 격자에 행이 하나 추가됩니다: 하나의 읽기와 하나의 시드에서 나온 세 개의 셀이므로, 나란히 놓인 두 셀은 밀기에서만 다르고 그 밖에는 다르지 않습니다. 각 행은 시작할 때 쓴 프롬프트를 그대로 간직하고, 얼마나 세게 밀었는지와 어느 레이어를 썼는지를 한 번 밝힙니다.',
        pairsSubtitleDetail: '세 쌍이며, 편집할 수 있고, 번호가 매겨져 있으며, 각 쌍은 한 가지에서만 달라야 합니다. 셋이 상한이기도 합니다: 쌍을 더하는 버튼은 셋에서 사라집니다. 한 번 실행이 끝나면 쌍들은 입력란 아래에 그림으로 한 번 더 섭니다 — 쌍마다 번호가 붙은 회색 화살표 하나가 자기 차이와 공통 방향 사이의 각도로 서고, 그 공통 방향을 나타내는 초록색 화살표가 하나 서며, 쓰기에 들어가는 것이 바로 그 방향입니다. 화살표들이 가까이 모여 있으면 쌍들이 같은 것에서 다르다는 뜻이고, 부채가 넓게 벌어지면 여러 가지에서 다르다는 뜻이며, 읽기는 그중 공통된 것만 남깁니다. 이 배치는 투영이며 손으로 그린 것이 아닙니다: 세 개의 차이는 서로 세 개의 각도로 서 있고, 평평한 종이 위 한 점에서 나온 세 광선에는 자유 매개변수가 둘 있으므로, 평면 그림은 세 각도 가운데 둘을 한 번에 담을 수 있습니다. 그려진 평면은 읽기 자체가 골라낸 평면 — 공통 방향을 따르고 그것을 가로지르는 평면 — 이며, 그 평면이 붙드는 퍼짐의 몫은 실행할 때마다 함께 돌아옵니다. 모든 화살표는 같은 길이로 그려집니다. 여기서 길이는 쌍이 아니라 그림에 대해 무언가를 말하게 되기 때문입니다. 모델의 가중치는 처음부터 끝까지 그대로입니다: 읽기와 밀기 모두 모델이 실행되는 동안 일어납니다. 한 쌍의 두 문장을 맞바꾸어도 측정에는 아무런 손실이 없습니다 — 방향은 외적들의 합의 고유벡터이고, 차이 하나를 뒤집어도 그 외적은 그대로이기 때문입니다 — 그저 그 화살표 하나가 방향을 돌릴 뿐입니다.',
        targetLayerHintDetail: '레이어는 스택 중간에 고정되어 있으며 화면에 조작부가 없습니다. 깊이는 같은 밀기가 무엇을 바꾸는지를 정합니다: 앞쪽 레이어는 아직 낱말 자체를 담고 있고, 마지막 레이어들은 이미 다음 낱말을 담고 있으며, 중간이 바로 주장이 주장으로서 서 있는 자리입니다 — 그래서 중간만이 읽을 수 있는 결과를 내놓는 설정이고, 나머지는 실행 한 번을 버리는 설정입니다. 이 값은 고른 모델에서 그때그때 가져오므로 그 모델 스택의 깊이를 따르며, 결과의 각 행은 자신이 쓴 번호를 밝힙니다. 이를 위한 축이 2026-08-25까지 화면에 있었고, 그 뒤 제거되었습니다.',
