        explainWhatTitle: 'MMAudio는 무엇을 하나요?',
        explainWhatText: 'MMAudio(Cheng et al., CVPR 2025)는 비디오와 오디오로 공동 학습되었습니다. 이미지를 텍스트로 변환한 다음 소리로 변환하는 것이 아니라, 같은 네트워크에서 이미지와 텍스트를 병렬 신호로 처리합니다. 모델은 어떤 소리가 어떤 시각적 장면에 속하는지 학습했습니다 — 숲은 새소리를, 거리는 교통 소음을, 기타는 현을 떵는 소리를 만들어냅니다.',
        explainHowTitle: '이 도구를 어떻게 사용하나요?',
        explainHowText: '이미지를 업로드하고/또는 텍스트 프롬프트를 입력하세요 — 둘 다 함께 사용하면 가장 풍부한 결과를 얻을 수 있습니다. 이미지만으로도 시각적 내용에 맞는 소리를 생성합니다. 텍스트 프롬프트는 소리를 추가로 조종하거나 이미지 없이 단독으로 사용할 수 있습니다. 네거티브 프롬프트에는 듣고 싶지 않은 소리를 설명하세요(예: “음성, 음악”). Duration은 길이를 설정합니다(1-8초). CFG Strength는 모델이 프롬프트를 얼마나 엄격하게 따르는지 제어합니다 — 낮은 값(2-3)은 더 다양한 결과를, 높은 값(6-8)은 더 프롬프트에 충실한 결과를 만듭니다.',
