        explainWhatTitle: 'ImageBind Guidance는 무엇을 하나요?',
        explainWhatText: 'ImageBind(Girdhar et al., CVPR 2023)는 여섯 가지 감각 — 이미지, 소리, 텍스트, 깊이, 열, 움직임 — 을 공유된 “언어”로 통합합니다. 이 도구는 그 공통 기반을 활용합니다: 소리가 단계별로 생성되는 동안 “이 소리가 이미지와 닮았나?”라고 계속 물으며 방향을 수정합니다. 결과에서 코사인 유사도는 생성된 소리가 이미지 내용에 얼마나 가까이 왔는지 보여줍니다.',
        explainHowTitle: '이 도구를 어떻게 사용하나요?',
        explainHowText: '이미지를 업로드하세요. 그 이미지가 소리의 목표 방향입니다. 텍스트 프롬프트는 선택 사항이며 추가로 조종합니다. 가이던스 강도 슬라이더가 이미지가 얼마나 멀리 끌어당길지 정합니다: 완성된 클립에서 측정했을 때 1 아래에서는 효과가 노이즈 안에 머물고, 5 언저리에서는 소리가 이미지 쪽으로 뚜렷하게 움직이며, 20을 넘으면 잠재 표현이 무너지고 유사도가 다시 떨어집니다. 가이던스 스텝 슬라이더는 그래디언트가 디노이징 스텝 가운데 몇 개에 작용하는지 말합니다. 이 샘플러는 매 스텝마다 새 노이즈를 섞어 넣으므로, 앞쪽 스텝에만 준 가이던스는 클립이 끝나기 전에 덮어써집니다. Total Steps와 Duration은 품질과 길이를 제어합니다.',
