        imageTypeText: 'ImageBind는 AudioSet(웹 비디오 클립 200만 개, 소리 카테고리 527개)으로 학습되었습니다. 소리와의 연관이 뚜렷한 이미지일수록 가장 강한 가이던스를 만듭니다: 동물(새, 개, 고양이), 자연(파도, 비, 폭포, 숲), 악기, 탈것(자동차, 비행기, 기차). 본래 소리가 없는 이미지 — 인물 사진, 건축, 추상 미술, 정물화 — 는 약하거나 일관되지 않은 결과를 만듭니다. 가장 좋은 결과를 위해서는 특정 소리가 바로 떠오르는 이미지를 선택하세요.',
