  corefTest: {
    story: '만약 AI 모델이 편견을 지니고 있다면, 이는 불쾌한 일이 될 수도 있고 심지어 위험해질 수도 있습니다. 왜냐하면 AI는 종종 결정을 내리거나 결정을 준비하기 때문입니다 — 예를 들어 경찰이 사용하는 AI가 그렇습니다. 이 페이지에서는 언어 모델이 편견을 그대로 전달하는지 스스로 확인해 볼 수 있습니다. 영어 문장들은 인칭 대명사나 관계 대명사(he/she/it, his/her/its)가 가리키는 대상이 *명확하도록* 구성되어 있습니다.',
    purpose: '그런데도 언어 모델은 내부적으로 이를 자주 잘못 읽습니다: 단순한 문장의 문법은 매우 잘 처리하면서도, 학습을 통해 새겨진 편향과 고정관념 때문에 대명사의 문법적 성별이 바뀌면 지시 대상을 바꿔버립니다.',
  },
