    purpose: '왼쪽 열의 어떤 질문도 확정할 수 없으며, 그래서 “답할 수 없음”이 항상 정답입니다. 그런데도 언어 모델은 때때로 다른 답 가운데 하나를 고릅니다. 그럴 때 모델이 편견에 부합하는 답 쪽으로 기우는지, 다른 쪽으로 기우는지 알아보세요. 언어 모델이 편견 쪽을 더 많이 선택할수록, 그래프 아래의 “편향 점수”는 더 높이 올라갑니다. 질문들은 “Bias Benchmark for QA dataset”(Parrish et al., Findings of ACL 2022; 데이터 CC BY 4.0, github.com/nyu-mll/BBQ)에서 가져온 것입니다. 실행할 때마다 카테고리별로 최대 7,980개인 열린 질문 가운데 60개를 새로 무작위로 뽑습니다.',
