        body: '1) eSpeak NG 1.51.1 (1995): AI 이전의 컴퓨터 목소리입니다. 포먼트 합성으로 작동합니다: 규칙이 글자를 음소로 바꾸고, 모든 음소가 몇 개의 공명으로 재생됩니다. 참조: "speak", Jonathan Duddington, 1995.\n\n2) Piper 1.6.0 (2022): 비자기회귀적입니다(VITS, 2021: 문장 하나가 한 번의 패스로 만들어지고, 음높이와 리듬은 실행할 때마다 새로 표집됩니다). 모든 목소리가 하나의 파일이며, 녹음된 데이터셋 하나로 학습되었고, 설치된 목소리 대부분은 영어 기본 목소리를 미세 조정한 것입니다: 고를 수 있는 것은 어느 목소리 모델이 말하는가이며, 들리는 화자는 녹음된 사람입니다. (Michael Hansen, Rhasspy 프로젝트, 2022; 설치된 1.6.0은 Home Assistant 저자들의 것, 2026) 독일어 목소리 "mls"에는 화자 236명이 하나의 모델 파일에 학습되어 있습니다. Piper는 실행마다 그중 한 명으로 말합니다. 이들은 LibriVox를 위해 저작권이 소멸된 책을 낭독한 자원 참여자들입니다. 연구용 말뭉치 Multilingual LibriSpeech가 이 녹음들을 담고 있습니다. "화자" 아래 드롭다운은 말뭉치 안의 번호로 각자를 표시하고, 파일 안에서의 색인을 괄호에 넣으며, 말뭉치가 기록한 성별과 녹음 분량을 덧붙입니다.\n\n3) Supertonic 3 (2026): 9,900만 파라미터. 비자기회귀적입니다(한 구절이 한 번의 패스로 만들어집니다). 음성 오토인코더 위의 flow-matching 디코더입니다. 열 개의 목소리가 벡터로 모델 안에 학습되어 있습니다. 단순한 덧셈과 정규화로 섞을 수 있습니다. 예: v = (v(F1) + v(F3) + v(M4)) / 3. (Supertone, 2026)\n\n4) VoxCPM2 (2026): 20억 파라미터. 확산-자기회귀적입니다(각 조각이 제자리로 디노이징되며, 문장 경계를 넘어서도 그다음 조각이 어떻게 읽힐지를 조건 짓습니다). 설정 파라미터가 없습니다. 입력 전체가 언어로 읽히며, 목소리에 대한 지시는 프롬프트 안에 심겨 이해됩니다. (OpenBMB, 2026)',
